function greet(name = "Guest", punct = "!") {
  return `${name}${punct}`;
}

greet();              // "Guest!"
greet("Ada");         // "Ada!"
greet("Ada", null);   // "Adanull" — null is not undefined
greet(undefined, "?"); // "Guest?"

function total(...nums) {
  return nums.reduce((sum, n) => sum + n, 0);
}

total(1, 2, 3); // 6

const arrow = (...items) => items.map(String);
arrow(1, true); // ["1", "true"]

function createUser({ name, role = "viewer", id = crypto.randomUUID() }) {
  return { name, role, id };
}

createUser({ name: "Sam" });
// { name: "Sam", role: "viewer", id: "..." }
